40: function terrainAt(x,y){if((x===12&&y>0&&y<8)||(x===11&&y===7)||(x===13&&y===2))return'water';if((x===1&&y===1)||(x===9&&y===2)||(x===7&&y===7)||(x===2&&y===6)||(x===13&&y===6))return'rock';let n=(x*37+y*71+x*y*13)%19;if(n<3)return'forest';if(n===4)return'flower';return'grass';}
41: function save(silent=false){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));if(!silent)toast('Seu reino foi salvo com sucesso.');}catch(e){if(!silent)toast('Não foi possível salvar neste navegador.');}}
42: function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&parsed.grid?.length===H&&parsed.resources){state=parsed;return true;}}}catch{}state=freshState();return false;}
43: function yearLabel(year){if(year<0)return `${Math.abs(year).toLocaleString('pt-BR')} a.C.`;return `${year.toLocaleString('pt-BR')} d.C.`;}
44: function eraIndex(){let i=0;for(let n=0;n<eras.length;n++)if(state.year>=eras[n].start)i=n;return i;}
45: function buildingCounts(){const c={};state.grid.flat().forEach(t=>{if(t.building)c[t.building.type]=(c[t.building.type]||0)+1});return c;}
46: function totalBuildings(){return state.grid.flat().filter(t=>t.building).length;}
47: function production(){const p={food:0,wood:0,stone:0,gold:0,knowledge:0};state.grid.flat().forEach(t=>{if(!t.building)return;const b=buildings[t.building.type];for(const k in b.yield)p[k]+=b.yield[k];});p.food-=state.population*.035;return p;}
48: function addLog(text){logItems.unshift({year:state.year,text});logItems=logItems.slice(0,5);renderLog();state.events=logItems;}
49: function renderLog(){const logs=$('#log');logs.innerHTML=logItems.slice(0,4).map(e=>`<li><span class="log-time">${yearLabel(e.year)}</span>${e.text}</li>`).join('')||'<li>Uma nova história começa...</li>';}
50: function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
51: function currentObjective(){const i=eraIndex(),count=totalBuildings(),target=Math.min(3+i,12),good=count>=target;const goals=['Reúna seu povo e erga as primeiras moradias.','Plante as sementes da civilização.','Desenvolva o comércio e o saber.','Faça de sua terra um centro de cultura.','Proteja o conhecimento e una o reino.','Espalhe novas ideias pelo mundo.','Construa um reino de máquinas e luz.','Conecte seu povo ao futuro.','Leve a humanidade ainda mais longe!'];return {text:good?(i<8?'Seu reino prospera. Continue expandindo!':'Você guiou sua terra através dos milênios!'):goals[i],target,progress:Math.min(count/target,1)};}
52: function renderUI(){const p=production();const bar=$('#resourcebar');bar.innerHTML=Object.entries(resources).map(([id,r])=>{const amount=state.resources[id]||0,rate=p[id]||0;return `<div class="resource"><span class="resource-icon">${r.icon}</span><div><div class="resource-name">${r.name}</div><div class="resource-val">${Math.floor(amount).toLocaleString('pt-BR')}</div></div><span class="resource-rate ${rate<0?'down':''}">${rate>0?'+':''}${rate.toFixed(1)}/a</span></div>`}).join('')+`<div class="year-card"><div><div class="year-small">ANO DO REINO</div><div class="year-value">${yearLabel(state.year)}</div></div><span class="era-pill">${eras[eraIndex()].name}</span></div>`;
53: $('#yearAside').textContent=yearLabel(state.year);$('#mapSub').textContent=`Terras livres · ${Math.floor(state.population).toLocaleString('pt-BR')} habitantes`;
54: const ti=$('#timeline');ti.innerHTML=eras.map((e,i)=>`<div class="era-row ${i<eraIndex()?'done':i===eraIndex()?'current':''}">${e.name}<span class="era-date">${e.date}</span></div>`).join('');
55: const ob=currentObjective();$('#objectiveText').textContent=ob.text;$('#objectiveProgress').style.width=`${ob.progress*100}%`;$('#objectiveCaption').textContent=`${Math.min(totalBuildings(),ob.target)} / ${ob.target} construções`;$('#objectivePct').textContent=`${Math.round(ob.progress*100)}%`;
56: const avail=Object.entries(buildings).filter(([id,b])=>state.year>=eras[b.era].start&&(!b.tech||state.techs.includes(b.tech)));const list=$('#buildingList');list.innerHTML=avail.map(([id,b])=>{const affordable=Object.entries(b.cost).every(([k,v])=>state.resources[k]>=v);const cost=Object.entries(b.cost).map(([k,v])=>`${resources[k].icon}${v}`).join(' ')||'Sem custo';const yieldText=Object.entries(b.yield).map(([k,v])=>`+${v} ${resources[k].icon}/ano`).join(' · ')||`+${b.capacity||0} vagas`;return `<button class="build-card ${selectedBuild===id?'active':''}" data-build="${id}" ${affordable?'':'disabled'} title="${b.desc}"><span class="build-emoji">${b.icon}</span><span class="build-name">${b.name}</span><div class="build-cost">${cost}</div><div class="build-yield">${yieldText}</div></button>`}).join('');list.querySelectorAll('[data-build]').forEach(btn=>btn.onclick=()=>{selectedBuild=selectedBuild===btn.dataset.build?null:btn.dataset.build;$('#mapTip').textContent=selectedBuild?`${buildings[selectedBuild].name} selecionado → clique num terreno`:'Escolha uma construção → clique no terreno';renderUI();drawMap();});
