58: function renderTech(){const i=eraIndex();const next=techs.find(t=>!state.techs.includes(t.id)&&i>=t.era);const area=$('#techArea');if(!next){area.innerHTML=`<div class="tech-card"><div class="tech-head"><span class="tech-name">✦ SABER DO REINO</span><span class="tech-era">${state.techs.length}/${techs.length}</span></div><div class="tech-desc">${i<1?'As descobertas virão com o passar das eras.':'Todas as descobertas desta era foram pesquisadas.'}</div></div>`;return;}const available=state.resources.knowledge>=next.cost;area.innerHTML=`<div class="tech-card"><div class="tech-head"><span class="tech-name">✦ ${next.name.toUpperCase()}</span><span class="tech-era">${eras[next.era].name}</span></div><div class="tech-desc">${next.desc}</div><button class="tech-btn" id="researchBtn" ${available?'':'disabled'}>PESQUISAR · ✳ ${next.cost}</button></div>`;$('#researchBtn').onclick=()=>research(next);}
59: function renderStats(p){const capacity=state.grid.flat().reduce((a,t)=>a+(t.building?(buildings[t.building.type].capacity||0):0),0);const stats=[['HABITANTES',Math.floor(state.population).toLocaleString('pt-BR'),`${Math.max(0,capacity-Math.floor(state.population))} vagas livres`],['TERRITÓRIO',`${totalBuildings()} / ${W*H}`,'lotes colonizados'],['CRESCIMENTO',`${(state.happiness>25?Math.max(.05,state.population*.008):0).toFixed(1)}`,'habitantes / ano'],['ERA',eras[eraIndex()].name,'na linha do tempo']];$('#townStats').innerHTML=stats.map(s=>`<div class="stat"><div class="stat-label">${s[0]}</div><div class="stat-value">${s[1]}</div><div class="stat-detail">${s[2]}</div></div>`).join('');$('#happyText').textContent=`${Math.round(state.happiness)}%`;$('#happyBar').style.width=`${state.happiness}%`;$('#happyBar').style.background=state.happiness<35?'#d78369':state.happiness<60?'#dfb967':'#a5ca78';}
60: function renderSelected(){const box=$('#selectedBox');if(!selectedTile){box.innerHTML='<div class="selected-title">Nenhuma construção selecionada</div><div class="selected-description">Clique num edifício no mapa para ver seus detalhes.</div>';return;}const t=state.grid[selectedTile.y][selectedTile.x];if(!t.building){box.innerHTML=`<div class="selected-title">Terreno livre · ${selectedTile.x+1}, ${selectedTile.y+1}</div><div class="selected-description">${selectedBuild?`Preparado para erguer ${buildings[selectedBuild].name}. Clique no mapa para confirmar.`:'Escolha uma construção para colonizar este lote.'}</div>`;return;}const b=buildings[t.building.type];box.innerHTML=`<div class="selected-title">${b.icon} ${b.name} · nível ${t.building.level||1}</div><div class="selected-description">${b.desc}<br>Produção: ${Object.entries(b.yield).map(([k,v])=>`+${v} ${resources[k].name.toLowerCase()}/ano`).join(' · ')||'Acolhe famílias'}</div>`;}
