function step(years){if(paused)return;const oldEra=eraIndex(),oldYear=state.year;state.year=Math.min(99999,state.year+years);state.playSeconds+=years/speeds[speedIndex];const p=production();for(const [k,v]of Object.entries(p))state.resources[k]=Math.max(0,Math.min(999999,(state.resources[k]||0)+v*years));state.resources.knowledge=Math.min(999999,state.resources.knowledge+years*.025);const capacity=state.grid.flat().reduce((a,t)=>a+(t.building?(buildings[t.building.type].capacity||0):0),0);const foodOkay=state.resources.food>0;const housed=state.population<capacity;const growth=(foodOkay&&housed&&state.happiness>20)?state.population*.008*years:0;state.population=Math.max(1,Math.min(capacity||1,state.population+growth));if(!foodOkay){state.population=Math.max(1,state.population-years*.003);state.happiness=Math.max(5,state.happiness-years*.04);}else state.happiness=Math.min(100,Math.max(35,state.happiness+years*.001));const newEra=eraIndex();if(newEra>oldEra){for(let i=oldEra+1;i<=newEra;i++){state.resources.knowledge+=7;addLog(`Uma nova era começa: ${eras[i].name.toLowerCase()}! +7 saber.`);}toast(`A humanidade entrou na era ${eras[newEra].name.toLowerCase()}!`);}if(oldYear<2026&&state.year>=2026){addLog('O reino alcançou a era moderna. O futuro está em suas mãos!');toast('Uma nova era da humanidade começa!');}if(state.playSeconds%12<years/speeds[speedIndex])save(true);}
